<?php if ( ! defined( 'ABSPATH' ) ) { exit; } $ids = function_exists( 'sd_core_blocked_ids' ) ? sd_core_blocked_ids() : array(); ?><section class="sd-privacy-panel"><h2><?php esc_html_e( 'Blocked members', 'social-discovery' ); ?></h2><?php if ( empty( $ids ) ) : ?><p class="sd-muted"><?php esc_html_e( 'You have not blocked anyone.', 'social-discovery' ); ?></p><?php else : ?><ul><?php foreach ( $ids as $id ) : $user = get_userdata( $id ); if ( $user ) : ?><li><?php echo esc_html( $user->display_name ); ?><button type="button" class="sd-block-button" data-sd-unblock-user="<?php echo esc_attr( $id ); ?>"><?php esc_html_e( 'Unblock', 'social-discovery' ); ?></button></li><?php endif; endforeach; ?></ul><?php endif; ?></section>
